// p5-b4 (QA SF1): writes lib/prompts-bundle.ts from the Markdown files in /prompts.
// Run after editing any prompt: `npm run prompts:bundle`. tests/unit/prompts-bundle.test.ts fails
// if the bundle and the files ever differ. No network, no secrets: it only reads /prompts.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dir = path.join(root, "prompts");
const files = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();

const lines = [
  "// GENERATED by scripts/make-prompts-bundle.mjs (`npm run prompts:bundle`). Do not edit by hand:",
  "// edit the Markdown file in /prompts, then run the script. tests/unit/prompts-bundle.test.ts checks",
  "// that every entry equals its file byte for byte.",
  "//",
  "// Why: a deployed Trigger.dev task has no /prompts folder on disk, so the prompt texts are embedded",
  "// here (bundled like any import) and lib/prompts.ts never reads a file at run time.",
  "export const PROMPT_FILES: Readonly<Record<string, string>> = {",
  ...files.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(path.join(dir, f), "utf8"))},`),
  "};",
  "",
];
writeFileSync(path.join(root, "lib", "prompts-bundle.ts"), lines.join("\n"));
console.log(`lib/prompts-bundle.ts: ${files.length} prompts`);
